formula:
round(
  (
    0 if (custom_current_net_total_earnings + gross_pay - LOPHRS) < 1200000 else
    (
      0 if (custom_current_net_total_earnings - gross_pay - LOPHRS) <= 400000 else
      (
        ((custom_current_net_total_earnings - gross_pay - LOPHRS) - 400000) * 0.05 if (custom_current_net_total_earnings - gross_pay - LOPHRS) <= 800000 else
        (
          400000 * 0.05 + ((custom_current_net_total_earnings - gross_pay - LOPHRS) - 800000) * 0.10 if (custom_current_net_total_earnings - gross_pay - LOPHRS) <= 1200000 else
          (
            400000 * 0.05 + 400000 * 0.10 + ((custom_current_net_total_earnings - gross_pay - LOPHRS) - 1200000) * 0.15
          )
        )
      )
    )
  ) * 1.04 - custom_income_tax
) / (custom_tax_calculation_month + 1)

(
  (
    ((custom_canteen_subsidy * (30 - custom_uploaded_leave_without_pay) / 30) - custom_canteen_recovery)
    if custom_uploaded_leave_without_pay > 10
    else (custom_canteen_subsidy - custom_canteen_recovery)
  )
  if BP > 0 and (custom_payroll_days - custom_uploaded_leave_without_pay) > 10
  else 0
)
